func (m *formMapper) setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSet bool, err error) {
	m.currentKey = tagValue
	m.formValues = form
	m.activeField = field
	m.activeTarget = value
	if m.mappingTag == "" {
		m.mappingTag = m.formTag
	}
	vs, ok := m.lookupFormValues(form, tagValue)
	if !ok && !m.formValuePresent(form, tagValue) && !opt.isDefaultExists {
		return false, nil
	}

	switch value.Kind() {
	case reflect.Slice:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		m.activeValues = vs
		return true, m.setSliceValues(vs, value, field)
	case reflect.Array:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		if len(vs) != value.Len() {
			return false, fmt.Errorf("%q is not valid value for %s", vs, value.Type().String())
		}
		m.activeValues = vs
		return true, m.setArrayValues(vs, value, field)
	default:
		var val string
		if !ok {
			val = m.applyDefaultValue(opt)
			if val == "" {
				val = opt.defaultValue
			}
		}
		if len(vs) > 0 {
			val = m.scalarFormValue(vs, opt)
		}
		m.activeValue = val
		return true, m.assignFormScalar(val, value, field)
	}
}

func (m *formMapper) setSliceValues(vals []string, value reflect.Value, field reflect.StructField) error {
	m.activeValues = vals
