	}
	slice := reflect.MakeSlice(value.Type(), len(vals), len(vals))
	err := m.setArrayValues(vals, slice, field)
	if err != nil {
		return err
	}
	value.Set(slice)
	return nil
}

func (m *formMapper) setArrayValues(vals []string, value reflect.Value, field reflect.StructField) error {
	m.activeValues = vals
	m.activeField = field
	if m.mappingTag == "" {
		m.mappingTag = m.formTag
	}
	for i, s := range vals {
		m.activeValue = s
		err := m.setWithProperType(s, value.Index(i), field)
		if err != nil {
			return err
		}
	}
	return nil
}

func (m *formMapper) setFormMap(ptr any, form map[string][]string) error {
	m.formValues = form
