package main

import (
	"bytes"
	"fmt"
	"mime/multipart"
	"net/http"

	"github.com/gin-gonic/gin/binding"
)

type BindFile struct {
	Name  string                `form:"name" binding:"required"`
	Email string                `form:"email" binding:"required"`
	File  *multipart.FileHeader `form:"file"`
}

func main() {
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	for name, val := range map[string]string{"name": "", "email": "", "file": ""} {
		_ = mw.WriteField(name, val)
	}
	_ = mw.Close()

	req, _ := http.NewRequest("POST", "/", &body)
	req.Header.Set("Content-Type", binding.MIMEMultipartPOSTForm+"; boundary="+mw.Boundary())

	var bindFile BindFile
	if err := binding.FormMultipart.Bind(req, &bindFile); err != nil {
		fmt.Println("FAIL:", err)
		return
	}
	fmt.Printf("OK: name=%q email=%q file=%v\n", bindFile.Name, bindFile.Email, bindFile.File)
}
